INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage, metric) VALUES ('f-elephant-mass', 'African elephant', 6000, 'kg', 'A large adult male African savanna elephant is on the order of 6 tonnes. Bulls vary widely.', 'https://en.wikipedia.org/wiki/African_bush_elephant', 'Wikipedia: African bush elephant', '2026-11-21', 'CC BY-SA 4.0', 'nature', 2, 0, 'Typical large male', 'animal-mass');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage, metric) VALUES ('f-whale-mass', 'Blue whale', 150000, 'kg', 'A large blue whale weighs on the order of 150 tonnes, far beyond any land animal alive today.', 'https://www.fisheries.noaa.gov/species/blue-whale', 'NOAA Fisheries', '2026-11-21', 'Public domain (U.S. government work)', 'nature', 2, 0, 'Order-of-magnitude adult', 'animal-mass');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage, metric) VALUES ('f-mouse-mass', 'House mouse', 0.02, 'kg', 'An adult house mouse weighs about 20 grams.', 'https://en.wikipedia.org/wiki/House_mouse', 'Wikipedia: House mouse', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, 'Typical adult', 'animal-mass');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage, metric) VALUES ('f-penguin-mass', 'Emperor penguin', 30, 'kg', 'An adult emperor penguin is around 30 kg. Weight swings a lot across the breeding season.', 'https://www.antarctica.gov.au/about-antarctica/animals/penguins/emperor-penguins/', 'Australian Antarctic Program', '2026-11-21', 'Australian Antarctic Program', 'nature', 2, 0, 'Typical adult', 'animal-mass');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage, metric) VALUES ('f-bear-mass', 'Polar bear', 450, 'kg', 'Adult male polar bears are often around 350 to 700 kg. 450 kg is a mid-range figure, not a record.', 'https://en.wikipedia.org/wiki/Polar_bear', 'Wikipedia: Polar bear', '2026-11-21', 'CC BY-SA 4.0', 'nature', 2, 0, 'Mid-range adult male', 'animal-mass');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage, metric) VALUES ('f-hippo-mass', 'Hippopotamus', 1500, 'kg', 'A large male hippopotamus is around 1,500 kg. Adults vary, and the order against a polar bear does not.', 'https://en.wikipedia.org/wiki/Hippopotamus', 'Wikipedia: Hippopotamus', '2026-11-21', 'CC BY-SA 4.0', 'nature', 2, 0, 'Typical large male', 'animal-mass');
INSERT INTO facts (id, label, value, unit, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, vintage, metric) VALUES ('f-albatross', 'Wingspan of a wandering albatross', 3.5, 'm', 'The wandering albatross has the largest wingspan of any living bird, up to about 3.5 m.', 'https://www.britannica.com/animal/wandering-albatross', 'Britannica: wandering albatross', '2026-11-21', 'Encyclopaedia Britannica (sample citation)', 'nature', 2, 0, 'Approximate maximum', 'wingspan');
