INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-moon', 'How far is the Moon from Earth, on average?', 'estimate', 'km', 'higher', 'distance-km', '["f-moon-distance"]', '["f-moon-distance"]', 'NASA gives the Moon''s average distance as 384,400 km. The orbit is slightly oval, so the real distance swings by tens of thousands of kilometres.', 'https://science.nasa.gov/moon/facts/', 'NASA Science', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-giants', 'Name a country in Central America.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Seven sovereign states sit on the Central American isthmus, from Guatemala to Panama. Mexico is counted with North America in this sample. Pending verification.', 'https://en.wikipedia.org/wiki/Central_America', 'Wikipedia: Central America', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Belize","prior":2,"aliases":[]},{"canonical":"Costa Rica","prior":8,"aliases":[]},{"canonical":"El Salvador","prior":3,"aliases":[]},{"canonical":"Guatemala","prior":3,"aliases":[]},{"canonical":"Honduras","prior":3,"aliases":[]},{"canonical":"Nicaragua","prior":3,"aliases":[]},{"canonical":"Panama","prior":8,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-orbits', 'Order these planets from closest to the Sun to farthest.', 'rank', NULL, 'lower', NULL, '["f-mercury-distance","f-venus-distance","f-earth-distance","f-mars-distance"]', '["f-earth-distance","f-mercury-distance","f-mars-distance","f-venus-distance"]', 'Average distances from the Sun run Mercury, Venus, Earth, then Mars: about 58 million km out to about 228 million km.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-light', 'What is the speed of light in a vacuum?', 'estimate', 'm/s', 'higher', 'speed-ms', '["f-light-speed"]', '["f-light-speed"]', 'Since 1983 the metre has been defined from this speed. In a vacuum, light travels at exactly 299,792,458 metres per second.', 'https://physics.nist.gov/cgi-bin/cuu/Value?c', 'NIST', '2026-11-21', 'Public domain (U.S. government work)', 'science', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-year', 'Name a country with more than 100 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The UN World Population Prospects 2024 median estimate puts 16 countries over 100 million, from India and China down to Vietnam. Iran sits just under the line. This sample list is not editorially verified.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"India","prior":30,"aliases":["Bharat","Republic of India"]},{"canonical":"China","prior":26,"aliases":["PRC","People''s Republic of China"]},{"canonical":"United States","prior":18,"aliases":["USA","US","U.S.","U.S.A.","America","United States of America"]},{"canonical":"Indonesia","prior":3,"aliases":[]},{"canonical":"Pakistan","prior":2,"aliases":[]},{"canonical":"Nigeria","prior":2,"aliases":[]},{"canonical":"Brazil","prior":6,"aliases":[]},{"canonical":"Bangladesh","prior":2,"aliases":[]},{"canonical":"Russia","prior":5,"aliases":["Russian Federation"]},{"canonical":"Ethiopia","prior":1,"aliases":[]},{"canonical":"Mexico","prior":3,"aliases":[]},{"canonical":"Japan","prior":4,"aliases":[]},{"canonical":"Philippines","prior":1,"aliases":[]},{"canonical":"Egypt","prior":1,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":1,"aliases":["DR Congo","DRC","Congo-Kinshasa","Democratic Republic of Congo"]},{"canonical":"Vietnam","prior":1,"aliases":["Viet Nam"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-everest', 'How high is Mount Everest above sea level?', 'estimate', 'm', 'higher', 'length-m', '["f-everest"]', '["f-everest"]', 'In 2020 Nepal and China jointly announced a height of 8,848.86 m, including the snow cap.', 'https://dos.gov.np/everest/index.html', 'Survey Department, Government of Nepal', '2026-11-21', 'Government of Nepal survey publication', 'geography', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-seas', 'Name a noble gas.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The noble gases are helium, neon, argon, krypton, xenon, radon, and oganesson, the last of which is only predicted to behave like the group. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Helium","prior":10,"aliases":[]},{"canonical":"Neon","prior":10,"aliases":[]},{"canonical":"Argon","prior":6,"aliases":[]},{"canonical":"Krypton","prior":1,"aliases":[]},{"canonical":"Xenon","prior":1,"aliases":[]},{"canonical":"Radon","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-oceans', 'Order these oceans by surface area, largest first.', 'rank', NULL, 'higher', NULL, '["f-pacific","f-atlantic","f-indian","f-arctic"]', '["f-arctic","f-indian","f-pacific","f-atlantic"]', 'Counting the Southern Ocean separately, the Pacific is still by far the largest of these four, and the Arctic is the smallest. Figures follow a NOAA compilation widely reprinted from the ocean article on Wikipedia.', 'https://en.wikipedia.org/wiki/Ocean', 'Wikipedia: Ocean, citing NOAA', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-trench', 'How deep is Challenger Deep, the deepest known point in the ocean?', 'estimate', 'm', 'higher', 'length-m', '["f-challenger"]', '["f-challenger"]', 'A 2020 crewed survey, reported by NOAA, put the deepest observed seafloor in Challenger Deep at 10,935 metres, give or take about 6 metres.', 'https://oceanexplorer.noaa.gov/ocean-fact/ocean-depth/', 'NOAA Ocean Exploration', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 3, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-peaks', 'Name a chemical element discovered after 1900.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Discovery years are conventional and a few were disputed for decades. This list starts with europium (1901) and runs through oganesson, and it leaves out radon, which was identified in 1900. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Europium","prior":1,"aliases":[]},{"canonical":"Lutetium","prior":1,"aliases":[]},{"canonical":"Protactinium","prior":1,"aliases":[]},{"canonical":"Hafnium","prior":1,"aliases":[]},{"canonical":"Rhenium","prior":1,"aliases":[]},{"canonical":"Technetium","prior":1,"aliases":[]},{"canonical":"Francium","prior":1,"aliases":[]},{"canonical":"Astatine","prior":1,"aliases":[]},{"canonical":"Promethium","prior":1,"aliases":[]},{"canonical":"Neptunium","prior":1,"aliases":[]},{"canonical":"Plutonium","prior":16,"aliases":[]},{"canonical":"Americium","prior":1,"aliases":[]},{"canonical":"Curium","prior":1,"aliases":[]},{"canonical":"Berkelium","prior":1,"aliases":[]},{"canonical":"Californium","prior":1,"aliases":[]},{"canonical":"Einsteinium","prior":4,"aliases":[]},{"canonical":"Fermium","prior":1,"aliases":[]},{"canonical":"Mendelevium","prior":1,"aliases":[]},{"canonical":"Nobelium","prior":1,"aliases":[]},{"canonical":"Lawrencium","prior":1,"aliases":[]},{"canonical":"Rutherfordium","prior":1,"aliases":[]},{"canonical":"Dubnium","prior":1,"aliases":[]},{"canonical":"Seaborgium","prior":1,"aliases":[]},{"canonical":"Bohrium","prior":1,"aliases":[]},{"canonical":"Hassium","prior":1,"aliases":[]},{"canonical":"Meitnerium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Roentgenium","prior":1,"aliases":[]},{"canonical":"Copernicium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Flerovium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Livermorium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-bones', 'How many bones are in a typical adult human skeleton?', 'estimate', 'bones', 'higher', 'count', '["f-bones-adult"]', '["f-bones-adult"]', 'Anatomy texts settle on 206 bones in a typical adult. The count can vary slightly with small sesamoid bones, and babies start with more that later fuse.', 'https://en.wikipedia.org/wiki/Human_skeleton', 'Wikipedia: Human skeleton', '2026-11-21', 'CC BY-SA 4.0', 'human-body', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-lungs', 'Name a halogen.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Group 17 is fluorine, chlorine, bromine, iodine, astatine, and tennessine. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Fluorine","prior":8,"aliases":[]},{"canonical":"Chlorine","prior":8,"aliases":[]},{"canonical":"Bromine","prior":1,"aliases":[]},{"canonical":"Iodine","prior":6,"aliases":[]},{"canonical":"Astatine","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-counts', 'Order these by how many a typical person has, fewest first.', 'rank', NULL, 'lower', NULL, '["f-baby-teeth","f-teeth","f-chromosomes"]', '["f-chromosomes","f-baby-teeth","f-teeth"]', 'Children have 20 baby teeth. A full adult set, including wisdom teeth, is 32. Most human cells carry 46 chromosomes.', 'https://www.genome.gov/about-genomics/fact-sheets/Chromosomes-Fact-Sheet', 'National Human Genome Research Institute', '2026-11-21', 'Public domain (U.S. government work)', 'human-body', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-neurons', 'About how many neurons are in an adult human brain?', 'estimate', 'neurons', 'higher', 'count', '["f-neurons"]', '["f-neurons"]', 'A 2009 count by Azevedo and colleagues estimated about 86 billion neurons in the adult male human brain, with a margin of a few billion.', 'https://pubmed.ncbi.nlm.nih.gov/19226510/', 'PubMed: Azevedo et al. 2009', '2026-11-21', 'Public research abstract', 'human-body', 3, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-gut', 'Name an African country with more than 50 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Using the UN 2024 estimates, nine African countries are at or above 50 million: Nigeria, Ethiopia, Egypt, DR Congo, Tanzania, South Africa, Kenya, Sudan, and Uganda. Algeria sits just below. Pending verification.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"Nigeria","prior":24,"aliases":[]},{"canonical":"Ethiopia","prior":8,"aliases":[]},{"canonical":"Egypt","prior":10,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":4,"aliases":["DR Congo","DRC","Congo-Kinshasa","Democratic Republic of Congo"]},{"canonical":"Tanzania","prior":3,"aliases":[]},{"canonical":"South Africa","prior":6,"aliases":[]},{"canonical":"Kenya","prior":3,"aliases":[]},{"canonical":"Sudan","prior":1,"aliases":[]},{"canonical":"Uganda","prior":1,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-order', 'Order these from earliest to latest.', 'rank', NULL, 'lower', NULL, '["f-clock","f-gutenberg","f-telescope","f-telephone"]', '["f-telephone","f-clock","f-telescope","f-gutenberg"]', 'The earliest recorded European mechanical clock is dated to 1283. Gutenberg''s metal type is traditionally placed around 1440, the telescope patent in 1608, and Bell''s telephone patent in 1876.', 'https://en.wikipedia.org/wiki/Clock', 'Wikipedia: Clock', '2026-11-21', 'CC BY-SA 4.0', 'inventions', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-piano', 'How many keys does a standard modern piano have?', 'estimate', 'keys', 'higher', 'count', '["f-piano"]', '["f-piano"]', 'The modern piano keyboard settled on 88 keys, from A0 to C8.', 'https://en.wikipedia.org/wiki/Musical_keyboard', 'Wikipedia: Musical keyboard', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-towers', 'Name an alkali metal.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The alkali metals are lithium, sodium, potassium, rubidium, caesium, and francium. Hydrogen is left off this list. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Lithium","prior":6,"aliases":[]},{"canonical":"Sodium","prior":8,"aliases":[]},{"canonical":"Potassium","prior":8,"aliases":[]},{"canonical":"Rubidium","prior":1,"aliases":[]},{"canonical":"Cesium","prior":1,"aliases":["Caesium"]},{"canonical":"Francium","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-empire', 'How tall is the Empire State Building, to the tip of its antenna?', 'estimate', 'm', 'higher', 'length-m', '["f-empire"]', '["f-empire"]', 'The building''s own fact sheet gives 1,454 feet to the tip, about 443.2 metres.', 'https://www.esbnyc.com/about/facts-figures', 'Empire State Building', '2026-11-21', 'Official building fact sheet', 'inventions', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-first', 'Name a country with fewer than 1 million people.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'A 2023 UN grouping of member states under 1 million runs from Fiji and Iceland through Tuvalu. This sample also accepts Vatican City, an observer state, and Vanuatu. Pending verification.', 'https://population.un.org/wpp/', 'United Nations population estimates, via UN member groupings', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"Iceland","prior":12,"aliases":[]},{"canonical":"Luxembourg","prior":8,"aliases":[]},{"canonical":"Malta","prior":4,"aliases":[]},{"canonical":"Brunei","prior":2,"aliases":["Brunei Darussalam"]},{"canonical":"Bahamas","prior":2,"aliases":["The Bahamas"]},{"canonical":"Maldives","prior":3,"aliases":[]},{"canonical":"Belize","prior":1,"aliases":[]},{"canonical":"Barbados","prior":2,"aliases":[]},{"canonical":"Fiji","prior":2,"aliases":[]},{"canonical":"Guyana","prior":1,"aliases":[]},{"canonical":"Suriname","prior":1,"aliases":[]},{"canonical":"Bhutan","prior":2,"aliases":[]},{"canonical":"Comoros","prior":1,"aliases":[]},{"canonical":"Solomon Islands","prior":1,"aliases":[]},{"canonical":"Cabo Verde","prior":1,"aliases":["Cape Verde"]},{"canonical":"Vanuatu","prior":1,"aliases":[]},{"canonical":"Samoa","prior":1,"aliases":[]},{"canonical":"Andorra","prior":2,"aliases":[]},{"canonical":"Monaco","prior":3,"aliases":[]},{"canonical":"Liechtenstein","prior":2,"aliases":[]},{"canonical":"San Marino","prior":1,"aliases":[]},{"canonical":"Vatican City","prior":4,"aliases":["Holy See"]},{"canonical":"Palau","prior":1,"aliases":[]},{"canonical":"Nauru","prior":1,"aliases":[]},{"canonical":"Tuvalu","prior":1,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Tonga","prior":1,"aliases":[]},{"canonical":"Seychelles","prior":1,"aliases":[]},{"canonical":"Grenada","prior":1,"aliases":[]},{"canonical":"Dominica","prior":1,"aliases":[]},{"canonical":"Saint Lucia","prior":1,"aliases":[]},{"canonical":"Antigua and Barbuda","prior":1,"aliases":[]},{"canonical":"Saint Kitts and Nevis","prior":1,"aliases":[]},{"canonical":"Saint Vincent and the Grenadines","prior":1,"aliases":["Saint Vincent and the Grenadines"]},{"canonical":"Marshall Islands","prior":1,"aliases":[]},{"canonical":"Micronesia","prior":1,"aliases":["Federated States of Micronesia"]},{"canonical":"Sao Tome and Principe","prior":1,"aliases":["São Tomé and Príncipe"]},{"canonical":"Montenegro","prior":2,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-pyramid', 'What was the original height of the Great Pyramid of Giza?', 'estimate', 'm', 'higher', 'length-m', '["f-pyramid-height"]', '["f-pyramid-height"]', 'The Great Pyramid originally rose about 146.6 m. The outer casing is gone, so it stands a little lower today.', 'https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza', 'Wikipedia: Great Pyramid of Giza', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-older', 'Name a member of the Group of Seven.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'The G7 is Canada, France, Germany, Italy, Japan, the United Kingdom, and the United States. The European Union attends but is not a country on this list. Pending verification.', 'https://www.international.gc.ca/world-monde/international_relations-relations_internationales/g7/index.aspx', 'Government of Canada: G7', '2026-11-21', 'Government of Canada public information', 'geography', 1, 0, '[{"canonical":"Canada","prior":4,"aliases":[]},{"canonical":"France","prior":8,"aliases":[]},{"canonical":"Germany","prior":4,"aliases":[]},{"canonical":"Italy","prior":4,"aliases":[]},{"canonical":"Japan","prior":4,"aliases":[]},{"canonical":"United Kingdom","prior":4,"aliases":["UK","Britain"]},{"canonical":"United States","prior":8,"aliases":["USA","US","America"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-timeline', 'Order these from oldest to newest.', 'rank', NULL, 'lower', NULL, '["f-pyramid-year","f-parthenon","f-colosseum","f-taj"]', '["f-taj","f-colosseum","f-pyramid-year","f-parthenon"]', 'Conventional completion dates: the Great Pyramid around 2560 BCE, the Parthenon in 438 BCE, the Colosseum in 80 CE, and the Taj Mahal complex in 1653. The pyramid''s exact year is debated; the order is not.', 'https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza', 'Wikipedia: Great Pyramid of Giza', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-liberty', 'How tall is the Statue of Liberty from the ground to the tip of the torch?', 'estimate', 'm', 'higher', 'length-m', '["f-liberty-total"]', '["f-liberty-total"]', 'The National Park Service lists the height from the ground to the tip of the torch as 92.99 metres. The figure of Liberty herself is 46 metres; the rest is the pedestal.', 'https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm', 'U.S. National Park Service', '2026-11-21', 'Public domain (U.S. government work)', 'culture', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-statues', 'Name a country with an area greater than 1 million square kilometres.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Total area, land plus inland water, from the standard country-area tables. Twenty-nine countries clear 1 million km². Tanzania and Nigeria fall short. Greenland is not counted here because it is not a country. Pending verification.', 'https://en.wikipedia.org/wiki/List_of_countries_and_dependencies_by_area', 'Wikipedia: List of countries and dependencies by area', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Russia","prior":16,"aliases":["Russian Federation"]},{"canonical":"Canada","prior":14,"aliases":[]},{"canonical":"China","prior":12,"aliases":["PRC","People''s Republic of China"]},{"canonical":"United States","prior":12,"aliases":["USA","US","America","United States of America"]},{"canonical":"Brazil","prior":8,"aliases":[]},{"canonical":"Australia","prior":8,"aliases":[]},{"canonical":"India","prior":6,"aliases":["Bharat"]},{"canonical":"Argentina","prior":3,"aliases":[]},{"canonical":"Kazakhstan","prior":2,"aliases":[]},{"canonical":"Algeria","prior":2,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":2,"aliases":["DR Congo","DRC","Democratic Republic of Congo"]},{"canonical":"Saudi Arabia","prior":2,"aliases":[]},{"canonical":"Mexico","prior":2,"aliases":[]},{"canonical":"Indonesia","prior":2,"aliases":[]},{"canonical":"Sudan","prior":1,"aliases":[]},{"canonical":"Libya","prior":2,"aliases":[]},{"canonical":"Iran","prior":2,"aliases":[]},{"canonical":"Mongolia","prior":2,"aliases":[]},{"canonical":"Peru","prior":1,"aliases":[]},{"canonical":"Chad","prior":1,"aliases":[]},{"canonical":"Niger","prior":1,"aliases":[]},{"canonical":"Angola","prior":1,"aliases":[]},{"canonical":"Mali","prior":1,"aliases":[]},{"canonical":"South Africa","prior":1,"aliases":[]},{"canonical":"Colombia","prior":1,"aliases":[]},{"canonical":"Ethiopia","prior":1,"aliases":[]},{"canonical":"Bolivia","prior":1,"aliases":[]},{"canonical":"Mauritania","prior":1,"aliases":[]},{"canonical":"Egypt","prior":1,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-whale', 'About how long can the largest blue whales grow?', 'estimate', 'm', 'higher', 'length-m', '["f-whale-length"]', '["f-whale-length"]', 'NOAA describes the largest blue whales as reaching about 30 metres. Most individuals are shorter. They are the largest animals known to have lived.', 'https://www.fisheries.noaa.gov/species/blue-whale', 'NOAA Fisheries', '2026-11-21', 'Public domain (U.S. government work)', 'nature', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-heavy', 'Name a country in Oceania.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'This sample accepts the sovereign states usually counted in Oceania, including Australia and New Zealand. Pending verification.', 'https://en.wikipedia.org/wiki/Oceania', 'Wikipedia: Oceania', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Australia","prior":16,"aliases":[]},{"canonical":"Fiji","prior":1,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Marshall Islands","prior":1,"aliases":[]},{"canonical":"Micronesia","prior":1,"aliases":[]},{"canonical":"Nauru","prior":1,"aliases":[]},{"canonical":"New Zealand","prior":8,"aliases":[]},{"canonical":"Palau","prior":1,"aliases":[]},{"canonical":"Papua New Guinea","prior":1,"aliases":[]},{"canonical":"Samoa","prior":1,"aliases":[]},{"canonical":"Solomon Islands","prior":1,"aliases":[]},{"canonical":"Tonga","prior":1,"aliases":[]},{"canonical":"Tuvalu","prior":1,"aliases":[]},{"canonical":"Vanuatu","prior":1,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-masses', 'Order these by typical adult body mass, lightest first.', 'rank', NULL, 'lower', NULL, '["f-mouse-mass","f-penguin-mass","f-bear-mass","f-hippo-mass"]', '["f-bear-mass","f-mouse-mass","f-hippo-mass","f-penguin-mass"]', 'Typical masses, not records: a house mouse around 20 grams, an emperor penguin around 30 kg, a male polar bear around 450 kg, and a large male hippo around 1,500 kg. Individuals vary, and the order does not.', 'https://en.wikipedia.org/wiki/Hippopotamus', 'Wikipedia: Hippopotamus', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-wings', 'What is the wingspan of the largest wandering albatrosses?', 'estimate', 'm', 'higher', 'length-m', '["f-albatross"]', '["f-albatross"]', 'The wandering albatross has the largest wingspan of any living bird, up to about 3.5 metres. It spends most of its life gliding over the Southern Ocean.', 'https://www.britannica.com/animal/wandering-albatross', 'Britannica: wandering albatross', '2026-11-21', 'Encyclopaedia Britannica (sample citation)', 'nature', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-gestation', 'Name a member of the European Union.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The European Union has 27 member states. The United Kingdom left in 2020, so it does not count. The list is the public membership roll and is still marked unverified in this sample.', 'https://european-union.europa.eu/principles-countries-history/country-profiles_en', 'European Union', '2026-11-21', 'European Union public information', 'geography', 1, 0, '[{"canonical":"Austria","prior":2,"aliases":[]},{"canonical":"Belgium","prior":3,"aliases":[]},{"canonical":"Bulgaria","prior":1,"aliases":[]},{"canonical":"Croatia","prior":1,"aliases":[]},{"canonical":"Cyprus","prior":1,"aliases":[]},{"canonical":"Czechia","prior":2,"aliases":["Czech Republic"]},{"canonical":"Denmark","prior":3,"aliases":[]},{"canonical":"Estonia","prior":1,"aliases":[]},{"canonical":"Finland","prior":2,"aliases":[]},{"canonical":"France","prior":14,"aliases":[]},{"canonical":"Germany","prior":14,"aliases":[]},{"canonical":"Greece","prior":4,"aliases":[]},{"canonical":"Hungary","prior":2,"aliases":[]},{"canonical":"Ireland","prior":3,"aliases":[]},{"canonical":"Italy","prior":8,"aliases":[]},{"canonical":"Latvia","prior":1,"aliases":[]},{"canonical":"Lithuania","prior":1,"aliases":[]},{"canonical":"Luxembourg","prior":2,"aliases":[]},{"canonical":"Malta","prior":1,"aliases":[]},{"canonical":"Netherlands","prior":4,"aliases":[]},{"canonical":"Poland","prior":4,"aliases":[]},{"canonical":"Portugal","prior":3,"aliases":[]},{"canonical":"Romania","prior":2,"aliases":[]},{"canonical":"Slovakia","prior":1,"aliases":[]},{"canonical":"Slovenia","prior":1,"aliases":[]},{"canonical":"Spain","prior":8,"aliases":[]},{"canonical":"Sweden","prior":3,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-un', 'How many member states does the United Nations have?', 'estimate', 'member states', 'higher', 'count', '["f-un-members"]', '["f-un-members"]', 'The United Nations has 193 member states. That count has been stable since South Sudan joined in 2011. The Holy See and Palestine are observer states, not members.', 'https://www.un.org/en/about-us/member-states', 'United Nations', '2026-11-21', 'United Nations public information', 'geography', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-canada', 'Name a permanent member of the United Nations Security Council.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The five permanent members are China, France, Russia, the United Kingdom, and the United States. Pending verification.', 'https://www.un.org/securitycouncil/content/current-members', 'United Nations Security Council', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"China","prior":6,"aliases":["PRC"]},{"canonical":"France","prior":6,"aliases":[]},{"canonical":"Russia","prior":6,"aliases":["Russian Federation"]},{"canonical":"United Kingdom","prior":6,"aliases":["UK","Britain"]},{"canonical":"United States","prior":6,"aliases":["USA","US","America"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-areas', 'Order these by total area, smallest first.', 'rank', NULL, 'lower', NULL, '["f-vatican-area","f-japan-area","f-mexico-area","f-brazil-area"]', '["f-brazil-area","f-vatican-area","f-mexico-area","f-japan-area"]', 'Vatican City is under half a square kilometre. Japan is about 378,000 km², Mexico about 2.0 million, and Brazil about 8.5 million.', 'https://www.cia.gov/the-world-factbook/countries/brazil/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-russia', 'What is the total area of Russia, including inland water?', 'estimate', 'km²', 'higher', 'area-km2', '["f-russia-area"]', '["f-russia-area"]', 'The CIA World Factbook gives Russia a total area of 17,098,242 km². It is the largest country on Earth by area.', 'https://www.cia.gov/the-world-factbook/countries/russia/', 'CIA World Factbook', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-brazil', 'Name a country in South America.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Twelve sovereign countries sit on the South American continent. French Guiana is not a country, so it is not accepted. Pending verification.', 'https://en.wikipedia.org/wiki/South_America', 'Wikipedia: South America', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Argentina","prior":6,"aliases":[]},{"canonical":"Bolivia","prior":2,"aliases":[]},{"canonical":"Brazil","prior":16,"aliases":[]},{"canonical":"Chile","prior":2,"aliases":[]},{"canonical":"Colombia","prior":2,"aliases":[]},{"canonical":"Ecuador","prior":2,"aliases":[]},{"canonical":"Guyana","prior":2,"aliases":[]},{"canonical":"Paraguay","prior":2,"aliases":[]},{"canonical":"Peru","prior":2,"aliases":[]},{"canonical":"Suriname","prior":2,"aliases":[]},{"canonical":"Uruguay","prior":2,"aliases":[]},{"canonical":"Venezuela","prior":2,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-c14', 'What is the half-life of carbon-14, in years?', 'estimate', 'years', 'higher', 'years', '["f-c14"]', '["f-c14"]', 'NIST describes carbon-14''s half-life as about 5,730 years. Radiocarbon labs still use an older conventional Libby value of 5,568 years for some calculations. This question uses 5,730.', 'https://www.nist.gov/how-do-you-measure-it/how-do-you-know-age-fossils-and-other-old-things', 'NIST', '2026-11-21', 'Public domain (U.S. government work)', 'science', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-melt', 'Name an alkaline earth metal.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Group 2 is beryllium, magnesium, calcium, strontium, barium, and radium. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Beryllium","prior":2,"aliases":[]},{"canonical":"Magnesium","prior":8,"aliases":[]},{"canonical":"Calcium","prior":8,"aliases":[]},{"canonical":"Strontium","prior":2,"aliases":[]},{"canonical":"Barium","prior":2,"aliases":[]},{"canonical":"Radium","prior":2,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-metals', 'Order these metals by melting point, lowest first.', 'rank', NULL, 'lower', NULL, '["f-tin-melt","f-gold-melt","f-iron-melt","f-tungsten-melt"]', '["f-tungsten-melt","f-tin-melt","f-iron-melt","f-gold-melt"]', 'At ordinary pressure, tin melts near 232 °C, gold near 1,064 °C, iron near 1,538 °C, and tungsten near 3,422 °C.', 'https://www.rsc.org/periodic-table/element/74/tungsten', 'Royal Society of Chemistry', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-sound', 'How fast does sound travel in dry air at 20 °C?', 'estimate', 'm/s', 'higher', 'speed-ms', '["f-sound"]', '["f-sound"]', 'In dry air at 20 °C, sound travels at about 343 metres per second. The speed rises as the air gets warmer, so the temperature is part of the question.', 'https://en.wikipedia.org/wiki/Speed_of_sound', 'Wikipedia: Speed of sound', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-atomic', 'Name a chemical element whose symbol is a single letter.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fourteen elements use a one-letter symbol: H, B, C, N, O, F, P, S, K, V, Y, I, W, and U. Gold is Au and lead is Pb, so neither counts. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Hydrogen","prior":10,"aliases":[]},{"canonical":"Boron","prior":3,"aliases":[]},{"canonical":"Carbon","prior":12,"aliases":[]},{"canonical":"Nitrogen","prior":6,"aliases":[]},{"canonical":"Oxygen","prior":12,"aliases":[]},{"canonical":"Fluorine","prior":3,"aliases":[]},{"canonical":"Phosphorus","prior":2,"aliases":[]},{"canonical":"Sulfur","prior":3,"aliases":["Sulphur"]},{"canonical":"Potassium","prior":3,"aliases":[]},{"canonical":"Vanadium","prior":1,"aliases":[]},{"canonical":"Yttrium","prior":1,"aliases":[]},{"canonical":"Iodine","prior":4,"aliases":[]},{"canonical":"Tungsten","prior":2,"aliases":["Wolfram"]},{"canonical":"Uranium","prior":8,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-marathon', 'How long is a standard marathon?', 'estimate', 'km', 'higher', 'distance-km', '["f-marathon"]', '["f-marathon"]', 'World Athletics sets the marathon at 42.195 km, the distance standardized from the 1908 London course.', 'https://worldathletics.org/disciplines/road-running/marathon', 'World Athletics', '2026-11-21', 'World Athletics competition rules', 'culture', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-premiere', 'Name a Nordic country.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'This sample treats the Nordic countries as Denmark, Finland, Iceland, Norway, and Sweden. Pending verification.', 'https://www.norden.org/en/information/facts-about-nordic-countries', 'Nordic Council', '2026-11-21', 'Nordic Council public information', 'geography', 1, 0, '[{"canonical":"Denmark","prior":4,"aliases":[]},{"canonical":"Finland","prior":4,"aliases":[]},{"canonical":"Iceland","prior":4,"aliases":[]},{"canonical":"Norway","prior":8,"aliases":[]},{"canonical":"Sweden","prior":8,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-works', 'Order these works by the year of their first performance, earliest first.', 'rank', NULL, 'lower', NULL, '["f-figaro","f-beethoven","f-rite","f-messiaen"]', '["f-rite","f-figaro","f-messiaen","f-beethoven"]', 'Figaro opened in 1786, Beethoven''s Ninth in 1824, The Rite of Spring in 1913, and Messiaen''s Quartet for the End of Time in a prisoner-of-war camp in 1941.', 'https://en.wikipedia.org/wiki/The_Marriage_of_Figaro', 'Wikipedia: The Marriage of Figaro', '2026-11-21', 'CC BY-SA 4.0', 'culture', 3, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-paintings', 'Name an Asian country with more than 50 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'UN 2024 estimates. Russia is left off this sample list so the question stays about Asia. Egypt is counted with Africa. Pending verification.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"India","prior":24,"aliases":["Bharat"]},{"canonical":"China","prior":22,"aliases":["PRC","People''s Republic of China"]},{"canonical":"Indonesia","prior":6,"aliases":[]},{"canonical":"Pakistan","prior":4,"aliases":[]},{"canonical":"Bangladesh","prior":3,"aliases":[]},{"canonical":"Japan","prior":8,"aliases":[]},{"canonical":"Philippines","prior":2,"aliases":[]},{"canonical":"Vietnam","prior":2,"aliases":["Viet Nam"]},{"canonical":"Iran","prior":2,"aliases":[]},{"canonical":"Turkey","prior":3,"aliases":["Turkiye","Türkiye"]},{"canonical":"Thailand","prior":2,"aliases":[]},{"canonical":"Myanmar","prior":1,"aliases":["Burma"]},{"canonical":"South Korea","prior":3,"aliases":["Republic of Korea"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-shakespeare', 'In what year was William Shakespeare born?', 'estimate', 'year', 'higher', 'years', '["f-shakespeare"]', '["f-shakespeare"]', 'Parish records show Shakespeare''s baptism on 26 April 1564. His birthday is traditionally marked on 23 April, but the birth date itself was not written down. The year was.', 'https://en.wikipedia.org/wiki/William_Shakespeare', 'Wikipedia: William Shakespeare', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-equator', 'What is the equatorial circumference of Earth?', 'estimate', 'km', 'higher', 'distance-km', '["f-equator"]', '["f-equator"]', 'NASA''s planetary fact sheet lists Earth''s equatorial circumference as 40,075 km. The polar circumference is a little shorter because Earth is not a perfect sphere.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'geography', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-span', 'Name a sovereign country in the Caribbean.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sovereign Caribbean states only. Territories such as Puerto Rico are not countries on this list. Pending verification.', 'https://en.wikipedia.org/wiki/Caribbean', 'Wikipedia: Caribbean', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Antigua and Barbuda","prior":2,"aliases":[]},{"canonical":"Bahamas","prior":2,"aliases":["The Bahamas"]},{"canonical":"Barbados","prior":2,"aliases":[]},{"canonical":"Cuba","prior":8,"aliases":[]},{"canonical":"Dominica","prior":2,"aliases":[]},{"canonical":"Dominican Republic","prior":2,"aliases":[]},{"canonical":"Grenada","prior":2,"aliases":[]},{"canonical":"Haiti","prior":2,"aliases":[]},{"canonical":"Jamaica","prior":8,"aliases":[]},{"canonical":"Saint Kitts and Nevis","prior":2,"aliases":[]},{"canonical":"Saint Lucia","prior":2,"aliases":[]},{"canonical":"Saint Vincent and the Grenadines","prior":2,"aliases":[]},{"canonical":"Trinidad and Tobago","prior":2,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-rocky', 'Order these planets by equatorial diameter, smallest first.', 'rank', NULL, 'lower', NULL, '["f-mercury-diameter","f-mars-diameter","f-venus-diameter","f-earth-diameter"]', '["f-earth-diameter","f-mercury-diameter","f-venus-diameter","f-mars-diameter"]', 'Mercury is the smallest, then Mars, then Venus, then Earth. Venus is only slightly smaller than Earth. Diameters are the equatorial figures from NASA''s fact sheets.', 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/', 'NASA Planetary Fact Sheet', '2026-11-21', 'Public domain (U.S. government work)', 'space', 2, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-elements', 'How many chemical elements are on the periodic table?', 'estimate', 'elements', 'higher', 'count', '["f-elements"]', '["f-elements"]', 'IUPAC''s periodic table currently lists 118 confirmed elements. The last of the newest names were adopted in 2016.', 'https://iupac.org/what-we-do/periodic-table-of-elements/', 'IUPAC', '2026-11-21', 'IUPAC', 'science', 1, 0, NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-trenches', 'Name a chemical element with an atomic number greater than 92.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Uranium is 92. Everything past it, from neptunium to oganesson, was made in a lab or a reactor. The names follow the IUPAC table. Pending verification.', 'https://iupac.org/what-we-do/periodic-table-of-elements/', 'IUPAC', '2026-11-21', 'IUPAC', 'science', 2, 0, '[{"canonical":"Neptunium","prior":1,"aliases":[]},{"canonical":"Plutonium","prior":18,"aliases":[]},{"canonical":"Americium","prior":1,"aliases":[]},{"canonical":"Curium","prior":1,"aliases":[]},{"canonical":"Berkelium","prior":1,"aliases":[]},{"canonical":"Californium","prior":1,"aliases":[]},{"canonical":"Einsteinium","prior":1,"aliases":[]},{"canonical":"Fermium","prior":1,"aliases":[]},{"canonical":"Mendelevium","prior":1,"aliases":[]},{"canonical":"Nobelium","prior":1,"aliases":[]},{"canonical":"Lawrencium","prior":1,"aliases":[]},{"canonical":"Rutherfordium","prior":1,"aliases":[]},{"canonical":"Dubnium","prior":1,"aliases":[]},{"canonical":"Seaborgium","prior":1,"aliases":[]},{"canonical":"Bohrium","prior":1,"aliases":[]},{"canonical":"Hassium","prior":1,"aliases":[]},{"canonical":"Meitnerium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Roentgenium","prior":1,"aliases":[]},{"canonical":"Copernicium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Flerovium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Livermorium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements');
